SELECT 
FROM approval_application a

WHERE a.tenant_id = #{tenantId}
  AND a.id = #{id}

SELECT 
FROM approval_application a

WHERE a.tenant_id = #{tenantId}
  AND a.applicant_user_id = #{userId}

    AND a.status = #{status}

ORDER BY a.created_at DESC, a.id DESC
LIMIT #{size} OFFSET #{offset}

